#!/usr/bin/env bash
# HG008: effect of the homopolymer compression of the index and of the search (--hpc --hpc-cap 2 in
# 03_vespa_index_search.sh). Same run as reads_ec_align; the only change: no homopolymer compression anywhere.
#   0. corrected normal reads, recovered from the EC BAM as germline_cascade/00_reads.sh did for the tumor
#   1-5. as 03_vespa_index_search.sh without --hpc: base index (GIAB v3 + normal unitigs, the unitigs regenerated by
#        germline_cascade/01_unitigs.sh, identical to the paper run), normal search, normal reads with SFS, full
#        index, tumor search, dedup_sfs.py with the 500 bp cap of the paper run
#   6. VESPA call, only s = 5 (the default run of 04_call.sh), 32 threads
#   7. Minda bench of the VESPA runs, as 05_bench.sh (PASS, regions, excluded-truth rule)
# Large intermediates (normal reads, normal SFS, normal reads added, raw tumor SFS) are deleted at the end; the
# index, the final SFS, the calls and the bench are kept. Output: $O. Usage: bash run.sh
set -euo pipefail
source "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")/../../config.sh"
R=$HG008/reads_ec_align
O=$R/nohpc
HERE=$(cd "$(dirname "$0")" && pwd)
HELPERS=$(cd $HERE/../bench && pwd)
V05=$HG008/ground_truths/v0.5
GIABV3=$REFS/GRCh38_GIABv3.fasta.gz
UNITIGS=$R/germline_cascade/unitigs/normal.r_utg.fa.gz
TUMOR_EC=$R/germline_cascade/reads/tumor.ec.fa.gz
REF=$R/ref/GRCh38_GIABv3.chr1-22X.fa
EXCLUDE=$REFS/grch38_centromers.bed
THREADS=48
THRESHOLDS="5"   # the weight of the analyses of S3 (2026-10-15); the grid is not needed here
mkdir -p $O/reads $O/index $O/search $O/calls $O/bench $O/time $O/logs
timed() { local name=$1; shift; /usr/bin/time -v -o $O/time/$name.txt "$@"; }
check_search() { grep -qa "All done!" $1 || { echo "search failed, see $1" >&2; exit 1; }; }
export PATH=$SV_BIN:$PATH
NORMAL_EC=$O/reads/normal.ec.fa.gz
BASE=$O/index/base.fmd; FULL=$O/index/full.fmd
# 0. normal reads
if [[ ! -s $NORMAL_EC ]]; then
  timed fasta_normal bash -o pipefail -c "$SAMTOOLS fasta -@ 8 -F 0x900 $R/align/normal.ec.hp.bam 2> $O/logs/normal.fasta.log | gzip -1 > $NORMAL_EC.part"
  mv $NORMAL_EC.part $NORMAL_EC
fi
# 1. base index
if [[ ! -s $BASE ]]; then
  timed vespa_index_base $VESPA index -d -m 4G -t $THREADS -p 0 $GIABV3 $UNITIGS -o $BASE.part > $O/logs/vespa_index_base.log 2>&1
  mv $BASE.part $BASE
fi
# 2. normal search
if [[ ! -s $O/search/normal.sfs ]]; then
  timed vespa_search_normal $VESPA search --index $BASE --fastx $NORMAL_EC --bsize 10000 --threads $THREADS \
    > $O/search/normal.sfs.part 2> $O/logs/vespa_search_normal.log
  check_search $O/logs/vespa_search_normal.log; mv $O/search/normal.sfs.part $O/search/normal.sfs
fi
# 3. normal reads with SFS
if [[ ! -s $O/reads/normal.missing.fa.gz ]]; then
  timed extract_missing_reads $PYTHON $LIB/extract_missing_reads.py $O/search/normal.sfs $NORMAL_EC $O/reads/normal.missing.part.fa.gz \
    2> $O/logs/extract_missing_reads.log
  mv $O/reads/normal.missing.part.fa.gz $O/reads/normal.missing.fa.gz
fi
# 4. full index
if [[ ! -s $FULL ]]; then
  timed vespa_index_full $VESPA index -d -m 4G -t $THREADS -p 0 -i $BASE $O/reads/normal.missing.fa.gz -o $FULL.part > $O/logs/vespa_index_full.log 2>&1
  mv $FULL.part $FULL
fi
# 5. tumor search and dedup with the cap of the paper run
if [[ ! -s $O/search/tumor.sfs ]]; then
  timed vespa_search_tumor $VESPA search --index $FULL --fastx $TUMOR_EC --bsize 10000 --threads $THREADS \
    > $O/search/tumor.sfs.part 2> $O/logs/vespa_search_tumor.log
  check_search $O/logs/vespa_search_tumor.log; mv $O/search/tumor.sfs.part $O/search/tumor.sfs
fi
[[ -s $O/search/tumor.dedup.cap500.sfs ]] || timed dedup_sfs $PYTHON $LIB/dedup_sfs.py $O/search/tumor.sfs \
  $O/search/tumor.dedup.cap500.sfs --max-length 500 2> $O/logs/dedup_sfs.log
# 6. calls
for t in $THRESHOLDS; do
  run=$(printf "t%02d" $t); o=$O/calls/$run
  [[ -s $o/calls.vcf ]] && continue
  rm -rf $o; mkdir -p $o
  timed vespa.$run $VESPA call --reference $REF --bam $R/align/tumor.ec.hp.bam --sfs $O/search/tumor.dedup.cap500.sfs \
    --normal-contigs-bam $R/align/normal.ec.hp.bam --bed-exclusion $EXCLUDE --min-cluster-weight $t --min-sv-length 50 \
    --min-mapq 60 --clipped --no-clipped-fallback --threads 32 > $o/calls.unsorted.vcf 2> $o/call.log
  $BCFTOOLS sort $o/calls.unsorted.vcf -o $o/calls.vcf && rm $o/calls.unsorted.vcf
done
# 7. bench
for regions in clonal clonal_and_subclonal; do
  d=$O/bench/$regions; rm -rf $d; mkdir -p $d/vcf
  cp $R/bench/$regions/gt.vcf $d/gt.vcf; : > $d/callers.tsv
  for t in $THRESHOLDS; do
    name=$(printf "VESPA_t%02d" $t)
    $PYTHON $HELPERS/prep_vcf.py $O/calls/$(printf "t%02d" $t)/calls.vcf $d/vcf/$name.vcf --bed $V05/GRCh38_HG008-T-V0.5_somatic-stvar-$regions.draftbenchmark.bed --pass-only
    echo -e "$d/vcf/$name.vcf\t$name" >> $d/callers.tsv
  done
  $MINDA_PYTHON $MINDA truthset --base $d/gt.vcf --tsv $d/callers.tsv --out_dir $d/out --tolerance 500 --min_size 50 \
    --sample_name HG008 > $d/minda.log 2>&1
  $PYTHON $HELPERS/minda_excluded_truth.py $d $R/bench/truth_all.vcf $MINDA_PYTHON $MINDA
  { echo -e "method\tcallset\tTP\tFP\tFN"
    awk -F'\t' 'NR > 1 {print "minda\t" $1 "\t" $2 "\t" $4 "\t" $3}' $d/out/results/overall_rule.tsv; } > $d/summary.tsv
done
# cleanup of the large intermediates
du -sh $O/reads $O/search/normal.sfs $O/search/tumor.sfs > $O/logs/sizes_before_cleanup.txt 2>/dev/null || true
rm -f $NORMAL_EC $O/reads/normal.missing.fa.gz $O/search/normal.sfs $O/search/tumor.sfs
echo "done"
